<?php

namespace App\Services\Chat;

/**
 * Answers of the login-page assistant. Static facts follow the Act (2017) and the Rules (2026); document lists and
 * step lists are built from config/attachments.php and config/steps.php, so they never go out of date.
 * Edit the texts here; no database and no outside service is used.
 */
class KnowledgeBase
{
    public const STARTERS = ['কিভাবে আবেদন করব?', 'প্রয়োজনীয় কাগজপত্র কী কী?', 'ধাপসমূহ কী কী?', 'সময়সীমা কত?', 'লগইন করতে পারছি না', 'আমার আবেদনের অবস্থা জানতে চাই'];

    private static function docList(array $items): string
    {
        $req = []; $cond = [];
        foreach ($items as $i) {
            $line = $i['no'] . '. ' . $i['title'] . ($i['tor'] ? ' (' . $i['tor'] . ')' : '');
            if ($i['mode'] === 'conditional') $cond[] = $line; else $req[] = $line . ($i['mode'] === 'review' ? ' — রিভিউ প্রয়োজন' : '');
        }
        return "বাধ্যতামূলক (" . count($req) . "টি):\n" . implode("\n", $req)
            . "\n\nশর্তসাপেক্ষ (" . count($cond) . "টি) — আবেদনের প্রথম ধাপের হ্যাঁ/না প্রশ্নের উত্তর \"হ্যাঁ\" হলে প্রয়োজন:\n" . implode("\n", $cond);
    }

    private static function stepOverview(array $steps): string
    {
        $phases = [];
        foreach ($steps as $s) { $phases[$s['phase'] ?? ''][] = $s['step_no']; }
        $out = [];
        foreach ($phases as $p => $nos) { if ($p !== '') $out[] = '• ' . $p . ' (ধাপ ' . $nos[0] . ($nos[count($nos) - 1] !== $nos[0] ? '–' . $nos[count($nos) - 1] : '') . ')'; }
        return implode("\n", $out);
    }

